package glitch

import data.glitch_lib

is_conditional_type_switch(type_int) {
    type_int == 2
}

is_conditional_type_if(type_int) {
    type_int == 1
}

has_external_input_source(expr) {
    walk(expr, [_, n])
    n.ir_type == "VariableReference"
    regex.match(`^(var\.|variable\.|data\.|each\.|lookup|for_each|workspace|environment|region|stage|input|parameter)`, n.value)
}

has_dynamic_source(expr) {
    walk(expr, [_, n])
    n.ir_type == "VariableReference"
}

has_function_call_source(expr) {
    walk(expr, [_, n])
    n.ir_type == "FunctionCall"
    regex.match(`^(lookup|map|select|match|case|when|switch)`, n.name)
}

is_security_relevant_attribute(attr_name) {
    regex.match(`(?i)^(tags|labels|metadata|policy|rule|action|effect|decision|encryption|tier|sku|size|class|instance_type|role|permission|access|network|vpc|subnet|security_group|firewall|acl)$`, attr_name)
}

# Check if conditional is inside a security-relevant context
is_security_context(node) {
    walk(input, [path, parent])
    parent.ir_type == "AtomicUnit"
    glitch_lib.all_attributes(parent)[_].name == attr_name
    is_security_relevant_attribute(attr_name)
} else {
    walk(input, [path, parent])
    parent.ir_type == "Attribute"
    is_security_relevant_attribute(parent.name)
}

# Check for explicit case/default handling in hash-based mappings (terraform lookup patterns)
hash_has_default_key(hash_val) {
    walk(hash_val.value, [_, elem])
    elem.ir_type == "KeyValue"
    regex.match(`^(default|_|otherwise|else|.*default.*)$`, elem.name)
}

# Check if conditional chain ends without else/default
conditional_chain_missing_default(conditional) {
    conditional.else_statement == null
} else {
    conditional.else_statement != null
    not conditional.else_statement.is_default
    conditional_chain_missing_default(conditional.else_statement)
}

# Find the root of a conditional chain
find_conditional_root(node, root) {
    walk(input, [path, candidate])
    candidate.ir_type == "ConditionalStatement"
    candidate.else_statement == node
    find_conditional_root(candidate, root)
} else {
    root := node
    node.is_top
}

# Main detection: switch statements without default
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all conditional statements
    conditionals := glitch_lib.all_conditional_statements(parent)
    cond := conditionals[_]

    # Must be switch type or if-else chain
    is_conditional_type_switch(cond.type)

    # Must have external/dynamic input
    has_external_input_source(cond.condition)

    # Check chain lacks default/else
    find_conditional_root(cond, root)
    conditional_chain_missing_default(root)

    # Elevate risk if in security context
    risk_level := "high" if {
        is_security_context(cond)
    } else := "medium"

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": sprintf("Missing default case in multiple condition expression - Conditional without catch-all handler may lead to undefined behavior for unhandled values. Risk: %s (CWE-478)", [risk_level])
    }
}

# Main detection: if-else chains without terminating else
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditionals := glitch_lib.all_conditional_statements(parent)
    cond := conditionals[_]

