    } else := "medium"

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": sprintf("Missing default case in multiple condition expression - If-else chain without terminating else may fall through unhandled. Risk: %s (CWE-478)", [risk_level])
    }
